\loigiai{
\begin{center}
\begin{tikzpicture}[>=stealth, line join=round, line cap=round, scale=0.58, font=\scriptsize]
\pgfmathsetmacro{\hm}{3.0}
\pgfmathsetmacro{\xM}{2.1}
\coordinate (B) at (0,0); \coordinate (D) at (5.4,0);
\coordinate (A) at (0,\hm); \coordinate (C) at (5.4,\hm); \coordinate (M) at (\xM,0);
\draw[thick] (B)--(A)--(M)--(C)--(D)--cycle;
\draw (0.28,0)--(0.28,0.28)--(0,0.28) (5.12,0)--(5.12,0.28)--(5.4,0.28);
\draw[red!75!black] ($(M)+(-0.6,0)$) arc (180:125:0.6);
\node[above left, red!75!black] at ($(M)+(-0.38,0.12)$) {$60^\circ$};
\draw[red!75!black] ($(M)+(0.75,0)$) arc (0:42:0.75);
