\node[left] at (0,\hm/2) {$h$};
\draw[<->, blue!75!black] (0,-0.82) -- (5.4,-0.82) node[midway, fill=white, inner sep=1pt] {$BD=100\,\text{m}$};
\foreach \p/\g in {A/above, B/below left, C/above, D/below right, M/below}
  \fill (\p) circle (1.3pt) node[\g] {$\p$};
